INSERT INTO `drug_interaction` (`id`, `drug_a`, `drug_b`, `level`, `description`, `advice`, `active`) VALUES (1,'YP001','YP002','╫Ш╪и','╟╒д╙нВажсКм╥Фъ©кК©м╛йТ╕б-дзУё╟╥юЮ©╧иЗкьё╛йТжь╦╢сцр╘ё╛╩АотжЬтЖ╪сдмр╘╥ГоусК╡╩а╪╥╢с╕','а╫уътЯр╩й╧сц╪╢©иё╛╠эцБнчж╦уВа╙╨о',1),(2,'YP004','YP005','╫Ш╪и','╦╢╥╫╦й╡щф╛╨╛╦й╡щкАё╛©ирЩфПк╝дфДСаТ║╒я╙я╧иЩ╦ъё╛ж╠╫счв©╧оУ╠╫╣ьф╫╣д╫╣я╧вВсц','╦ъя╙я╧╩╪уъ╠эцБм╛сцё╛╦дсцфДкШж╧©хр╘нО',1),(3,'YP003','YP005','иВсц','╡╪бЕ╥рйТ╥гГчлЕ©╧явр╘ё╛©и╪УхУ╫╣я╧р╘афп╖╡╒╣╪жбя╙я╧иЩ╦ъ','пХ╪Ю╡Бя╙я╧ё╩Ё╓фзй╧сцс╕╦Э╩╩уРм╢╥╫╟╦',1),(4,'YP003','YP010','иВсц','цимяй╞и╒╬ъспг©нЭ╦╫вВсцё╛╩АотжЬ╫╣╣м╡╪бЕ╥р╣днЭйуё╛с╟оЛуРм╢п╖╧Ш','а╫р╘╥Чсц╪Д╦Тс╕тз 2 п║й╠ртио',1),(5,'YP001','YP006','в╒рБ','╟╒д╙нВажсК╢С╩╥дзУ╔юЮ╟╒фФц╧кьа╙сцё╛©╧╬Зфвжь╣Чё╛пХспцВх╥а╙╨осцр╘ж╦уВ','нчцВх╥ж╦уВй╠сеох╣╔р╘жнаф',1),(6,'YP004','YP009','в╒рБ','╦╢╥╫╦й╡щф╛сКянкА╟╠ДЕкВм╛н╙ж╧©х╩╞л╣юЮр╘нОё╛вВсцжь╦╢','тЯр╩й╧сцё╛╠эцБжь╦╢сцр╘',1),(7,'YP001','YP014','╫Ш╪и','╟╒д╙нВажсКгЮц╧кьV╪ьм╛йТгЮц╧кьюЮё╛жь╦╢сцр╘тЖ╪с╧ЩцТсКдмр╘╥Гоу','а╫уътЯр╩й╧сц',1),(8,'YP011','YP002','╫Ш╪и','м╥Фъъ╩паУ╔сКм╥Фъ©кК©м╛йТм╥Фъ╬ЗкьюЮё╛йТжь╦╢сцр╘','а╫уътЯр╩й╧сц',1),(9,'YP018','YP003','╫Ш╪и','к╚бх╥ркАдфсК╡╪бЕ╥рм╛йТ╥гГчлЕ©╧явр╘ё╛╨осцотжЬтЖ╪соШ╩╞╣юЁЖя╙╥Гоу','╠эцБа╙сцё╛тЯр╩й╧сц',1),(10,'YP015','YP022','╫Ш╪и','©кю╜ц╧кь▐┼п╖ржжфCYP3A4ё╛й╧кШм║юЮя╙р╘е╗╤хиЩ╦ъё╛тЖ╪с╨Анф╪║хэ╫Б╥Гоу','╦дсц╡╩╫⌡CYP3A4╢Зп╩╣д©╧иЗкь',1),(11,'YP020','YP005','╫Ш╪и','╟╠бх╣ьф╫сКоУ╠╫╣ьф╫м╛йТ╦фм╗╣ювХжм╪аё╛жь╦╢╫╣я╧рвжб╣мя╙я╧','а╫уътЯр╩й╧сц',1),(12,'YP012','YP026','иВсц','бал╪кАц╬©иРЭ╨оЮ╜е╣м╙юЮё╛отжЬ╫╣╣мвСяУ╥ЗиЁпгнЭйу','а╫р╘╪Д╦Т 2 п║й╠ртио╥Чсц',1),(13,'YP034','YP021','иВсц','цюмпбЕ╤Ш©ияз╦г╣мя╙лгж╒в╢║╒яс╩╨я╙лг╩ж╦╢','╪с▐┼я╙лг╪Ю╡Б',1),(14,'YP019','YP005','иВсц','хШю╢нТ╡╪ржжфг╟апоыкь╨оЁиё╛©и╪УхУ╫╣я╧афп╖╡╒иЩ╦ъя╙я╧','╪Ю╡Бя╙я╧',1),(15,'YP006','YP022','иВсц','╢С╩╥дзУ╔юЮ©ииЩ╦ъкШм║юЮя╙р╘е╗╤х','╪Ю╡Б╪║кА╪╓ц╦сК╪║м╢ж╒в╢',1),(16,'YP029','YP012','иВсц','вСяУ╥ЗиЁпгржжф╡Х╪Н╢Зп╩ё╛рвжб╟╠╡Х╪Нжп╤╬','╪Ю╡Б╡Х╪Ня╙р╘е╗╤х',1),(17,'YP012','YP025','в╒рБ','вСяУ╥ЗиЁпгсК╟бцюю╜ъР╬Ы╬╜╦нр╘ц╦╢Зп╩ё╛а╙сцпХаТрБ','╠ьр╙й╠╢М©╙╥Чр╘й╠╪Д',1),(18,'YP033','YP022','в╒рБ','╤Ч╪вк╚КрсКкШм║юЮа╙сцпХ╧ьв╒╦н╧╕дэ','╤╗фз╦╢╡И╦н╧╕дэ',1),(19,'YP037','YP036','в╒рБ','нВлФюШЮ╨сКбхювкШ╤╗м╛йТ©╧вИ╟╥р╘ё╛вВсцжь╦╢','тЯр╩й╧сц',1),(20,'YP023','YP030','в╒рБ','оУкА╦йсмсКиЁ╤║╟╥╢╪╬Ы©ижбпдбй╪с©Лё╛а╙сцпХ╧ш╡Л','╪Ю╡БпдбйсКя╙я╧',1),(21,'YP018','YP021','в╒рБ','к╚бх╥ркАдф©и╪УхУцюмпбЕ╤Ш╫╣я╧п╖╧Ш','╪Ю╡Бя╙я╧',1),(22,'YP013','YP028','в╒рБ','╪воУъРсК╩Н╬Зжф╪ам╛╥Ч╩А╫╣╣м╩Н╬Зафп╖','╢М©╙ 2 п║й╠ртио',1);
